"use client";
import { useEffect, useRef, useSyncExternalStore, type PointerEvent } from "react";
import { X } from "lucide-react";
import { reducedMotionNow } from "../hooks/reduced-motion";
import { SPRINGS, stepSpring, type SpringState } from "../hooks/overlay";
import { QUIET_MS } from "../hooks/latency";

// --- Store -----------------------------------------------------------------

export type ToastTone = "neutral" | "success" | "error" | "loading";

export interface ToastOptions {
  /** Reuse an id to update a toast in place instead of adding another. */
  id?: string;
  description?: string;
  tone?: ToastTone;
  /** How long it stays, in ms. Infinity keeps it until dismissed. */
  duration?: number;
  /** One action, such as Undo. A toast with an action stays until dismissed unless you set a duration. */
  action?: { label: string; onClick: () => void };
}

type ToastRecord = {
  id: string;
  title: string;
  description?: string;
  tone: ToastTone;
  duration: number;
  action?: ToastOptions["action"];
  open: boolean;
  /** Bumped on every update, so the timer restarts and the update is announced. */
  version: number;
};

const DURATION: Record<ToastTone, number> = { neutral: 5000, success: 4000, error: 8000, loading: Infinity };

let toasts: ToastRecord[] = [];
let counter = 0;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((notify) => notify());
const subscribe = (notify: () => void) => {
  listeners.add(notify);
  return () => listeners.delete(notify);
};
const EMPTY: ToastRecord[] = [];

const upsert = (title: string, opts: ToastOptions = {}) => {
  const id = opts.id ?? `toast-${++counter}`;
  const tone = opts.tone ?? "neutral";
  const existing = toasts.find((t) => t.id === id);
  const record: ToastRecord = {
    id,
    title,
    description: opts.description,
    tone,
    // Something to act on needs time to be read and reached (WCAG 2.2.1), so it waits.
    duration: opts.duration ?? (opts.action ? Infinity : DURATION[tone]),
    action: opts.action,
    open: true,
    version: (existing?.version ?? 0) + 1,
  };
  toasts = existing ? toasts.map((t) => (t.id === id ? record : t)) : [...toasts, record];
  emit();
  return id;
};

const dismiss = (id?: string) => {
  toasts = toasts.map((t) => (!id || t.id === id ? { ...t, open: false } : t));
  emit();
};

const remove = (id: string) => {
  toasts = toasts.filter((t) => t.id !== id);
  emit();
};

type Message<T> = string | ((value: T) => string);
const say = <T,>(m: Message<T>, value: T) => (typeof m === "function" ? m(value) : m);

/**
 * Show a toast. Returns its id.
 *
 * `toast.promise` follows the latency rule: nothing appears for a request
 * that settles inside `quietMs`, so a fast save goes straight to "Saved"
 * without a loading toast flashing first.
 */
export const toast = Object.assign((title: string, opts?: ToastOptions) => upsert(title, opts), {
  success: (title: string, opts?: Omit<ToastOptions, "tone">) => upsert(title, { ...opts, tone: "success" }),
  error: (title: string, opts?: Omit<ToastOptions, "tone">) => upsert(title, { ...opts, tone: "error" }),
  dismiss,
  promise: <T,>(
    promise: Promise<T>,
    messages: { loading: string; success: Message<T>; error: Message<unknown> },
    { quietMs = QUIET_MS }: { quietMs?: number } = {}
  ) => {
    const id = `toast-${++counter}`;
    const timer = window.setTimeout(() => upsert(messages.loading, { id, tone: "loading" }), quietMs);
    promise.then(
      (value) => {
        window.clearTimeout(timer);
        upsert(say(messages.success, value), { id, tone: "success" });
      },
      (err: unknown) => {
        window.clearTimeout(timer);
        upsert(say(messages.error, err), { id, tone: "error" });
      }
    );
    return promise;
  },
});

// --- Toaster ---------------------------------------------------------------

export interface ToasterProps {
  /** The corner it stacks in. Default: "bottom-right" */
  position?: "bottom-right" | "bottom-left" | "top-right" | "top-left";
  /** How many show in the collapsed stack. Default: 3 */
  visible?: number;
  /** Key that moves focus to the notifications, so keyboard users can reach an action. Default: "F8" */
  hotkey?: string;
  /** Accessible name of the region. Default: "Notifications" */
  label?: string;
}

type Motion = {
  y: SpringState;
  scale: SpringState;
  h: SpringState;
  x: SpringState;
  /** 0 entering or gone, 1 present. */
  presence: SpringState;
  remaining: number;
  version: number;
  xTarget: number;
  drag: { id: number; start: number; last: number; lastT: number; v: number; live: boolean } | null;
};

const GAP = 8;
const PEEK = 10;
const SWIPE_AT = 80;

const TONE_DOT: Record<ToastTone, string> = {
  neutral: "bg-white/50",
  success: "bg-[#86efac] shadow-[0_0_8px_#86efac]",
  error: "bg-[#fca5a5] shadow-[0_0_8px_#fca5a5]",
  loading: "bg-white/70 motion-safe:animate-pulse",
};

/**
 * Where toasts appear. Render one, near the root, then call `toast()` from
 * anywhere.
 *
 * The newest sits in front with the last few peeking out behind it. Hover or
 * focus fans the stack out so each can be read, and pauses every timer, as
 * does switching away from the tab. A toast can be swiped sideways to dismiss;
 * the spring picks up the swipe's speed. Each one is announced through a live
 * region (errors assertively), and F8 moves focus to them so an Undo is
 * reachable from the keyboard.
 *
 * @example
 * <Toaster />
 * toast.success("Saved");
 * toast("Moved to archive", { action: { label: "Undo", onClick: restore } });
 * toast.promise(save(), { loading: "Saving…", success: "Saved", error: "Could not save" });
 */
export const Toaster = ({ position = "bottom-right", visible = 3, hotkey = "F8", label = "Notifications" }: ToasterProps) => {
  const list = useSyncExternalStore(subscribe, () => toasts, () => EMPTY);
  const sectionRef = useRef<HTMLElement>(null);
  const itemRefs = useRef(new Map<string, HTMLLIElement>());
  const cardRefs = useRef(new Map<string, HTMLDivElement>());
  const innerRefs = useRef(new Map<string, HTMLDivElement>());
  const motion = useRef(new Map<string, Motion>());
  const hovering = useRef(false);
  const focusWithin = useRef(false);
  const listRef = useRef(list);
  const politeRef = useRef<HTMLDivElement>(null);
  const assertiveRef = useRef<HTMLDivElement>(null);
  const announced = useRef(new Map<string, number>());
  const top = position.startsWith("top");
  const dir = top ? 1 : -1; // which way the stack grows

  useEffect(() => {
    listRef.current = list;
  }, [list]);

  // Top layer, so a toast is never buried under a stacking context. Raise it again when a new one arrives.
  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;
    try {
      if (focusWithin.current) return;
      if (el.matches(":popover-open")) el.hidePopover();
      el.showPopover();
    } catch {
      // No Popover API: it is still fixed-position.
    }
  }, [list.length]);

  // Announce what is new or changed. Visible toasts are not a live region, so nothing is read twice.
  useEffect(() => {
    for (const t of list) {
      if (!t.open || announced.current.get(t.id) === t.version) continue;
      announced.current.set(t.id, t.version);
      const text = [t.title, t.description].filter(Boolean).join(". ");
      // Cleared first, then written, so the same message twice is still read twice.
      const region = (t.tone === "error" ? assertiveRef : politeRef).current;
      if (!region) continue;
      region.textContent = "";
      window.setTimeout(() => (region.textContent = text), 60);
    }
  }, [list]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== hotkey) return;
      const el = sectionRef.current;
      if (!el || listRef.current.every((t) => !t.open)) return;
      e.preventDefault();
      el.focus();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [hotkey]);

  const hasToasts = list.length > 0;

  // One loop moves the whole stack.
  useEffect(() => {
    if (!hasToasts) return;
    let raf = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const dt = (now - last) / 1000;
      last = now;
      const reduced = reducedMotionNow();
      const records = listRef.current;
      const paused = hovering.current || focusWithin.current || document.hidden;
      const live = records.filter((t) => t.open).reverse(); // newest first
      const expanded = hovering.current || focusWithin.current;

      // Natural heights, newest first, for the expanded layout.
      const heights = live.map((t) => innerRefs.current.get(t.id)?.offsetHeight ?? 56);
      const frontHeight = heights[0] ?? 0;
      // Fanned out, each toast sits past every newer one.
      const offsets: number[] = [];
      let offset = 0;
      for (const height of heights) {
        offsets.push(offset);
        offset += height + GAP;
      }

      for (const t of records) {
        let m = motion.current.get(t.id);
        if (!m) {
          m = {
            y: { x: 0, v: 0 },
            scale: { x: 1, v: 0 },
            h: { x: innerRefs.current.get(t.id)?.offsetHeight ?? 56, v: 0 },
            x: { x: 0, v: 0 },
            presence: { x: 0, v: 0 },
            remaining: t.duration,
            version: t.version,
            xTarget: 0,
            drag: null,
          };
          motion.current.set(t.id, m);
        }
        if (m.version !== t.version) {
          m.version = t.version;
          m.remaining = t.duration;
        }

        const slot = live.indexOf(t);
        const natural = innerRefs.current.get(t.id)?.offsetHeight ?? m.h.x;
        let yTarget = m.y.x;
        let scaleTarget = 1;
        let hTarget = natural;
        let shown = 0;

        if (slot >= 0) {
          if (expanded) {
            yTarget = dir * offsets[slot];
          } else {
            yTarget = dir * slot * PEEK;
            scaleTarget = 1 - slot * 0.05;
            // Behind the front one, a toast takes the front's height so only its edge shows.
            if (slot > 0) hTarget = frontHeight;
          }
          shown = slot < visible || expanded ? 1 : 0;
          if (!paused && Number.isFinite(m.remaining) && !m.drag) {
            m.remaining -= dt * 1000;
            if (m.remaining <= 0) dismiss(t.id);
          }
        }

        const presenceTarget = t.open ? shown : 0;
        if (reduced) {
          m.y = { x: yTarget, v: 0 };
          m.scale = { x: scaleTarget, v: 0 };
          m.h = { x: hTarget, v: 0 };
        } else {
          stepSpring(m.y, yTarget, SPRINGS.stack, dt);
          stepSpring(m.scale, scaleTarget, SPRINGS.stack, dt);
          stepSpring(m.h, hTarget, SPRINGS.stack, dt);
        }
        stepSpring(m.presence, presenceTarget, SPRINGS.panel, dt);
        if (!m.drag) stepSpring(m.x, m.xTarget, SPRINGS.panel, dt);

        if (!t.open && m.presence.x <= 0.01 && m.presence.v <= 0) {
          motion.current.delete(t.id);
          announced.current.delete(t.id);
          remove(t.id);
          continue;
        }

        const li = itemRefs.current.get(t.id);
        const card = cardRefs.current.get(t.id);
        if (li && card) {
          const p = Math.min(1, Math.max(0, m.presence.x));
          // Entering toasts rise in from the edge; with reduced motion they only fade.
          const enter = reduced ? 0 : (1 - p) * 16 * -dir;
          li.style.transform = `translate(${m.x.x.toFixed(2)}px, ${(m.y.x + enter).toFixed(2)}px) scale(${m.scale.x.toFixed(4)})`;
          li.style.opacity = (p * (1 - Math.min(1, Math.abs(m.x.x) / 360))).toFixed(3);
          li.style.zIndex = String(slot >= 0 ? 100 - slot : 0);
          li.style.pointerEvents = t.open && shown ? "auto" : "none";
          card.style.height = `${Math.max(0, m.h.x).toFixed(2)}px`;
          const inner = innerRefs.current.get(t.id);
          if (inner) inner.style.opacity = slot > 0 && !expanded ? "0" : "1";
        }
      }

      const section = sectionRef.current;
      if (section) section.style.height = `${Math.max(frontHeight, expanded ? offset - GAP : frontHeight + Math.min(live.length - 1, visible - 1) * PEEK) + GAP}px`;
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [hasToasts, visible, dir]);

  const onPointerDown = (id: string) => (e: PointerEvent<HTMLLIElement>) => {
    if (e.button !== 0 || (e.target as HTMLElement).closest("button")) return;
    const m = motion.current.get(id);
    if (!m) return;
    m.drag = { id: e.pointerId, start: e.clientX, last: e.clientX, lastT: e.timeStamp, v: 0, live: false };
  };

  const onPointerMove = (id: string) => (e: PointerEvent<HTMLLIElement>) => {
    const m = motion.current.get(id);
    const d = m?.drag;
    if (!m || !d || d.id !== e.pointerId) return;
    const dx = e.clientX - d.start;
    if (!d.live && Math.abs(dx) > 6) {
      d.live = true;
      e.currentTarget.setPointerCapture(e.pointerId);
    }
    if (!d.live) return;
    d.v = (e.clientX - d.last) / Math.max(1, e.timeStamp - d.lastT);
    d.last = e.clientX;
    d.lastT = e.timeStamp;
    m.x = { x: dx, v: 0 };
  };

  const onPointerUp = (id: string) => (e: PointerEvent<HTMLLIElement>) => {
    const m = motion.current.get(id);
    const d = m?.drag;
    if (!m || !d || d.id !== e.pointerId) return;
    m.drag = null;
    if (!d.live) return;
    m.x.v = d.v * 1000;
    const dx = m.x.x;
    if (Math.abs(dx) > SWIPE_AT || Math.abs(d.v) > 0.5) {
      m.xTarget = Math.sign(dx || d.v) * 420;
      dismiss(id);
    } else {
      m.xTarget = 0;
    }
  };

  const corner = {
    // A popover starts at inset: 0, so the far edges are unset explicitly.
    "bottom-right": "top-auto left-auto bottom-4 right-4",
    "bottom-left": "top-auto right-auto bottom-4 left-4",
    "top-right": "bottom-auto left-auto top-4 right-4",
    "top-left": "bottom-auto right-auto top-4 left-4",
  }[position];

  return (
    <>
      <div ref={politeRef} className="sr-only" role="status" aria-live="polite" aria-atomic="true" />
      <div ref={assertiveRef} className="sr-only" role="alert" aria-live="assertive" aria-atomic="true" />
      <section
        ref={sectionRef}
        popover="manual"
        aria-label={`${label} (${hotkey})`}
        tabIndex={-1}
        onPointerEnter={() => (hovering.current = true)}
        onPointerLeave={() => (hovering.current = false)}
        onFocus={() => (focusWithin.current = true)}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node | null)) focusWithin.current = false;
        }}
        className={`pointer-events-none fixed m-0 w-[min(360px,calc(100vw-2rem))] overflow-visible border-0 bg-transparent p-0 text-white outline-none ${corner}`}
      >
        <ol className="relative h-full">
          {list.map((t) => (
            <li
              key={t.id}
              ref={(el) => {
                if (el) itemRefs.current.set(t.id, el);
                else itemRefs.current.delete(t.id);
              }}
              onPointerDown={onPointerDown(t.id)}
              onPointerMove={onPointerMove(t.id)}
              onPointerUp={onPointerUp(t.id)}
              onPointerCancel={onPointerUp(t.id)}
              className={`absolute inset-x-0 touch-pan-y select-none ${top ? "top-0 origin-top pb-2" : "bottom-0 origin-bottom pt-2"}`}
              style={{ opacity: 0 }}
            >
              <div
                ref={(el) => {
                  if (el) cardRefs.current.set(t.id, el);
                  else cardRefs.current.delete(t.id);
                }}
                className="overflow-hidden rounded-xl border border-white/[0.1] bg-[#0d0d0d]/95 shadow-[0_14px_40px_rgba(0,0,0,0.5)] backdrop-blur-md"
              >
                <div
                  ref={(el) => {
                    if (el) innerRefs.current.set(t.id, el);
                    else innerRefs.current.delete(t.id);
                  }}
                  className="flex items-start gap-3 py-3 pl-4 pr-2"
                >
                  <span aria-hidden="true" className={`mt-[7px] h-1.5 w-1.5 shrink-0 rounded-full ${TONE_DOT[t.tone]}`} />
                  <div className="min-w-0 flex-1">
                    <p className="text-[13px] leading-5 text-white/90">{t.title}</p>
                    {t.description && <p className="mt-0.5 text-[12px] leading-relaxed text-white/50">{t.description}</p>}
                  </div>
                  {t.action && (
                    <button
                      type="button"
                      onClick={() => {
                        t.action?.onClick();
                        dismiss(t.id);
                      }}
                      className="shrink-0 rounded-lg border border-white/[0.12] bg-white/[0.05] px-2.5 py-1 text-[12px] text-white/85 hover:bg-white/[0.09] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
                    >
                      {t.action.label}
                    </button>
                  )}
                  <button
                    type="button"
                    aria-label={`Dismiss: ${t.title}`}
                    onClick={() => dismiss(t.id)}
                    className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-white/40 hover:bg-white/[0.06] hover:text-white/80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60"
                  >
                    <X size={14} />
                  </button>
                </div>
              </div>
            </li>
          ))}
        </ol>
      </section>
    </>
  );
};

"use client";
import { useCallback, useEffect, useReducer, useRef, useState } from "react";

/**
 * Latency states: one honest lifecycle for anything that waits on a request.
 *
 * It is a state, not a component. The async button and the loading region
 * both run on it, and anything else that waits (a select that fetches its
 * options, a search box, a save bar) can take the same hook and get the same
 * timing rules for free:
 *
 * - pending: a request is out but under the skeleton threshold, so nothing
 *   new is drawn. A fast response never flashes a placeholder.
 * - skeleton: it has passed that threshold (only if you ask for one).
 * - slow: it has taken long enough that the interface should say so.
 * - success / error / cancelled: settled. START runs it again, RESET clears it.
 */
/** Under this, show nothing new: a fast response never flashes a placeholder. Shared by every waiting surface. */
export const QUIET_MS = 400;
/** Past this with no progress, say it is slow and offer a way out. */
export const SLOW_MS = 2000;

export type LatencyPhase = "idle" | "pending" | "skeleton" | "slow" | "success" | "error" | "cancelled";

export type LatencyEvent = "START" | "SHOW_SKELETON" | "SLOW" | "RESOLVE" | "REJECT" | "CANCEL" | "RESET";

/** Every legal transition. Anything not listed is ignored, so a late result cannot move a settled state. */
export const LATENCY_TRANSITIONS: Record<LatencyPhase, Partial<Record<LatencyEvent, LatencyPhase>>> = {
  idle: { START: "pending" },
  pending: { SHOW_SKELETON: "skeleton", SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  skeleton: { SLOW: "slow", RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  slow: { RESOLVE: "success", REJECT: "error", CANCEL: "cancelled" },
  success: { START: "pending", RESET: "idle" },
  error: { START: "pending", RESET: "idle" },
  cancelled: { START: "pending", RESET: "idle" },
};

export const latencyReducer = (state: LatencyPhase, event: LatencyEvent): LatencyPhase =>
  LATENCY_TRANSITIONS[state][event] ?? state;

/**
 * The part of the machine one component uses: only these phases, reached
 * only by these events. A component that never shows a skeleton or never
 * cancels draws its own machine from this, and it is still the shared one.
 */
export const sliceTransitions = <P extends LatencyPhase, E extends LatencyEvent>(phases: readonly P[], events: readonly E[]) =>
  Object.fromEntries(
    phases.map((from) => [
      from,
      Object.fromEntries(
        Object.entries(LATENCY_TRANSITIONS[from]).filter(
          ([event, to]) => events.includes(event as E) && phases.includes(to as P)
        )
      ),
    ])
  ) as Record<P, Partial<Record<E, P>>>;

export const isBusy = (phase: LatencyPhase) => phase === "pending" || phase === "skeleton" || phase === "slow";

export interface LatencyLogEntry {
  /** Milliseconds since the request started (0 for START). */
  atMs: number;
  event: LatencyEvent;
  from: LatencyPhase;
  to: LatencyPhase;
}

export interface LatencyOptions<T> {
  /** The request. Honour `signal` if you can; late results are ignored either way. */
  run: (signal: AbortSignal) => Promise<T>;
  /** Show a skeleton after this long. Leave undefined to never show one. */
  skeletonAfterMs?: number;
  /** Say it is slow after this long. */
  slowAfterMs?: number;
  /** Return to idle this long after success. Leave undefined to stay on success. */
  successHoldMs?: number;
  /** Every real state change, with time since the request started. */
  onEvent?: (entry: LatencyLogEntry) => void;
}

/**
 * Run a request through the latency states.
 *
 * @example
 * const { phase, start } = useLatency({ run: (signal) => fetch("/api", { signal }), slowAfterMs: 1500 });
 */
export const useLatency = <T>({ run, skeletonAfterMs, slowAfterMs = SLOW_MS, successHoldMs, onEvent }: LatencyOptions<T>) => {
  const [phase, dispatch] = useReducer(latencyReducer, "idle");
  const phaseRef = useRef<LatencyPhase>("idle");
  const [data, setData] = useState<{ value: T } | null>(null);
  const [error, setError] = useState("");
  const [elapsedS, setElapsedS] = useState(0);

  const requestId = useRef(0);
  const startedAt = useRef(0);
  const timers = useRef<number[]>([]);
  const ticker = useRef<number | null>(null);
  const controller = useRef<AbortController | null>(null);
  const mounted = useRef(true);
  const onEventRef = useRef(onEvent);
  useEffect(() => {
    onEventRef.current = onEvent;
  }, [onEvent]);

  const stopTimers = () => {
    timers.current.forEach((t) => window.clearTimeout(t));
    timers.current = [];
    if (ticker.current !== null) window.clearInterval(ticker.current);
    ticker.current = null;
  };

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      stopTimers();
      controller.current?.abort();
    };
  }, []);

  /** Dispatch only legal events, and report real changes. */
  const send = useCallback((event: LatencyEvent) => {
    const from = phaseRef.current;
    const to = latencyReducer(from, event);
    if (to === from) return false;
    phaseRef.current = to;
    dispatch(event);
    const atMs = event === "START" ? 0 : Math.round(performance.now() - startedAt.current);
    onEventRef.current?.({ atMs, event, from, to });
    return true;
  }, []);

  const start = useCallback(() => {
    if (isBusy(phaseRef.current)) return;
    stopTimers();
    startedAt.current = performance.now();
    if (!send("START")) return;
    const id = ++requestId.current;
    const ctl = new AbortController();
    controller.current = ctl;
    const live = () => mounted.current && id === requestId.current;

    if (skeletonAfterMs !== undefined) {
      timers.current.push(window.setTimeout(() => live() && send("SHOW_SKELETON"), skeletonAfterMs));
    }
    timers.current.push(
      window.setTimeout(() => {
        if (!live()) return;
        send("SLOW");
        const tick = () => setElapsedS(Math.floor((performance.now() - startedAt.current) / 1000));
        tick();
        ticker.current = window.setInterval(tick, 250);
      }, slowAfterMs)
    );

    Promise.resolve()
      .then(() => run(ctl.signal))
      .then(
        (value) => {
          if (!live()) return;
          stopTimers();
          setData({ value });
          send("RESOLVE");
          if (successHoldMs !== undefined) {
            timers.current.push(window.setTimeout(() => live() && send("RESET"), successHoldMs));
          }
        },
        (err: unknown) => {
          if (!live()) return;
          stopTimers();
          setError(err instanceof Error ? err.message : "Request failed");
          send("REJECT");
        }
      );
  }, [run, send, skeletonAfterMs, slowAfterMs, successHoldMs]);

  const cancel = useCallback(() => {
    if (!isBusy(phaseRef.current)) return;
    requestId.current++; // a late result can no longer move the state
    stopTimers();
    controller.current?.abort();
    send("CANCEL");
  }, [send]);

  const reset = useCallback(() => {
    requestId.current++;
    stopTimers();
    send("RESET");
  }, [send]);

  return { phase, busy: isBusy(phase), data, error, elapsedS, start, cancel, reset };
};

"use client";
import { useCallback, useEffect, useLayoutEffect, useRef, useState, type RefObject } from "react";

/**
 * The overlay layer: what every popover, menu, dialog, sheet and toast shares.
 *
 * - Springs that are integrated against real time, so a 120Hz screen moves
 *   them at the same speed as a 60Hz one.
 * - Presence: an overlay stays mounted until its exit spring has finished,
 *   then unmounts. Closing is never a cut.
 * - One dismiss stack: Escape closes the top layer only, and a click outside
 *   closes every layer that does not hold it, from the top down.
 * - Scroll lock and focus return for modals.
 *
 * Why not the browser's light dismiss? `popover="auto"` and `<dialog>` close
 * instantly, which leaves no room for an exit spring. So overlays use
 * `popover="manual"` for the top layer and do the dismissing here.
 */

// --- Springs ---------------------------------------------------------------

export type Spring = { k: number; d: number };
export type SpringState = { x: number; v: number };

/** The same constants the command palette and select use, so every overlay feels like one family. */
export const SPRINGS = {
  panel: { k: 200, d: 24 },
  indicator: { k: 180, d: 22 },
  stack: { k: 220, d: 26 },
} as const satisfies Record<string, Spring>;

/** Advance a spring by `dt` seconds, in fixed 1/120s substeps (semi-implicit Euler). */
export const stepSpring = (s: SpringState, target: number, { k, d }: Spring, dt: number) => {
  let left = Math.min(Math.max(dt, 0), 0.064); // a long pause (tab switch) does not fling it
  while (left > 0) {
    const h = Math.min(left, 1 / 120);
    s.v += (k * (target - s.x) - d * s.v) * h;
    s.x += s.v * h;
    left -= h;
  }
};

export const atRest = (s: SpringState, target: number, eps = 0.0005) =>
  Math.abs(target - s.x) < eps && Math.abs(s.v) < eps * 20;

// --- Presence --------------------------------------------------------------

/**
 * Keep something mounted while it animates out.
 *
 * `render(p)` is called every frame with progress from 0 (gone) to 1 (fully
 * present) and should write styles straight to the DOM, so nothing re-renders
 * per frame. Reversing mid-flight carries the velocity over.
 *
 * Returns `drive` and `kick` so a drag can move the progress by hand and
 * hand it back to the spring on release.
 */
export const usePresence = (open: boolean, render: (p: number) => void, spring: Spring = SPRINGS.panel) => {
  const [mounted, setMounted] = useState(open);
  if (open && !mounted) setMounted(true);

  const state = useRef<SpringState>({ x: 0, v: 0 });
  const raf = useRef(0);
  const openRef = useRef(open);
  const renderRef = useRef(render);
  useLayoutEffect(() => {
    renderRef.current = render;
    openRef.current = open;
  });

  const kick = useCallback(() => {
    if (raf.current) return;
    let last = performance.now();
    const tick = (now: number) => {
      const target = openRef.current ? 1 : 0;
      stepSpring(state.current, target, spring, (now - last) / 1000);
      last = now;
      // Leaving is done once it is invisible; there is no need to wait out the tail.
      const done = target === 1 ? atRest(state.current, 1) : state.current.x <= 0.01;
      if (done) state.current = { x: target, v: 0 };
      renderRef.current(state.current.x);
      if (done) {
        raf.current = 0;
        if (!openRef.current) setMounted(false);
        return;
      }
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
  }, [spring]);

  useLayoutEffect(() => {
    if (!mounted) return;
    renderRef.current(state.current.x); // first frame before paint, so it never flashes in at full size
    kick();
  }, [open, mounted, kick]);

  useEffect(
    () => () => {
      cancelAnimationFrame(raf.current);
      raf.current = 0;
    },
    []
  );

  /** Set progress (and velocity, in progress per second) by hand. Call `kick` to let the spring carry on. */
  const drive = useCallback((x: number, v = 0) => {
    state.current = { x, v };
  }, []);

  return { mounted, drive, kick };
};

// --- Dismiss stack ---------------------------------------------------------

export type DismissReason = "escape" | "outside" | "focus-out" | "select" | "button";

type Layer = { contains: (node: Node) => boolean; dismiss: (reason: DismissReason) => void };

const layers: Layer[] = [];

const onKeyDown = (e: KeyboardEvent) => {
  if (e.key !== "Escape" || e.isComposing) return;
  const top = layers[layers.length - 1];
  if (!top) return;
  // Default-prevented, so a native dialog underneath does not also close.
  e.preventDefault();
  e.stopPropagation();
  top.dismiss("escape");
};

const onPointerDown = (e: PointerEvent) => {
  const target = e.target;
  if (!(target instanceof Node)) return;
  for (const layer of [...layers].reverse()) {
    if (layer.contains(target)) break;
    layer.dismiss("outside");
  }
};

const listen = (on: boolean) => {
  if (on) {
    window.addEventListener("keydown", onKeyDown, true);
    window.addEventListener("pointerdown", onPointerDown, true);
  } else {
    window.removeEventListener("keydown", onKeyDown, true);
    window.removeEventListener("pointerdown", onPointerDown, true);
  }
};

/**
 * Put a layer on the dismiss stack while `active`. Layers opened later sit
 * above earlier ones, so a menu inside a dialog closes before the dialog does.
 */
export const useDismissLayer = (active: boolean, contains: (node: Node) => boolean, dismiss: (reason: DismissReason) => void) => {
  const live = useRef({ contains, dismiss });
  useLayoutEffect(() => {
    live.current = { contains, dismiss };
  });
  useEffect(() => {
    if (!active) return;
    const layer: Layer = {
      contains: (node) => live.current.contains(node),
      dismiss: (reason) => live.current.dismiss(reason),
    };
    layers.push(layer);
    if (layers.length === 1) listen(true);
    return () => {
      const i = layers.indexOf(layer);
      if (i >= 0) layers.splice(i, 1);
      if (layers.length === 0) listen(false);
    };
  }, [active]);
};

// --- Focus -----------------------------------------------------------------

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

export const focusablesIn = (root: Element | null): HTMLElement[] =>
  root ? [...root.querySelectorAll<HTMLElement>(FOCUSABLE)].filter((el) => el.getClientRects().length > 0) : [];

/** Focus `[data-autofocus]` if there is one, else the first focusable, else the root itself. */
export const focusInitial = (root: HTMLElement | null) => {
  if (!root) return;
  const el = root.querySelector<HTMLElement>("[data-autofocus]") ?? focusablesIn(root)[0] ?? root;
  el.focus({ preventScroll: true });
};

// --- Scroll lock -----------------------------------------------------------

let locks = 0;
let saved = { overflow: "", paddingRight: "" };

/** Stop the page scrolling behind a modal, without the layout jumping when the scrollbar goes. Nested locks count. */
export const lockScroll = () => {
  const html = document.documentElement;
  if (locks++ === 0) {
    const gap = window.innerWidth - html.clientWidth;
    saved = { overflow: html.style.overflow, paddingRight: html.style.paddingRight };
    html.style.overflow = "hidden";
    if (gap > 0) html.style.paddingRight = `${gap}px`;
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--locks === 0) {
      html.style.overflow = saved.overflow;
      html.style.paddingRight = saved.paddingRight;
    }
  };
};

// --- Modal -----------------------------------------------------------------

export interface ModalOptions {
  open: boolean;
  onDismiss: (reason: DismissReason) => void;
  dialogRef: RefObject<HTMLDialogElement | null>;
  /** The visible panel. A press anywhere else (the backdrop) is outside. */
  panelRef: RefObject<HTMLElement | null>;
  /** Whether a press on the backdrop dismisses. Off for confirmations. */
  dismissOnOutside?: boolean;
  render: (p: number) => void;
}

/**
 * A native `<dialog>` opened with showModal(), so the browser makes the rest
 * of the page inert and puts it in the top layer, with a spring on both ways.
 *
 * Focus moves to `[data-autofocus]` (or the first control) on open and back to
 * whatever opened it once it has gone.
 */
export const useModal = ({ open, onDismiss, dialogRef, panelRef, dismissOnOutside = true, render }: ModalOptions) => {
  const presence = usePresence(open, render);
  const { mounted } = presence;
  const onDismissRef = useRef(onDismiss);
  useLayoutEffect(() => {
    onDismissRef.current = onDismiss;
  });

  useLayoutEffect(() => {
    const dialog = dialogRef.current;
    if (!mounted || !dialog) return;
    const invoker = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const release = lockScroll();
    if (!dialog.open) dialog.showModal();
    focusInitial(panelRef.current);
    return () => {
      release();
      if (dialog.open) dialog.close();
      if (invoker?.isConnected) invoker.focus({ preventScroll: true });
    };
  }, [mounted, dialogRef, panelRef]);

  // The browser can still ask to close (Android back, a close watcher): route it through the spring.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!mounted || !dialog) return;
    const onCancel = (e: Event) => {
      e.preventDefault();
      onDismissRef.current("escape");
    };
    dialog.addEventListener("cancel", onCancel);
    return () => dialog.removeEventListener("cancel", onCancel);
  }, [mounted, dialogRef]);

  useDismissLayer(
    open,
    (node) => !!panelRef.current?.contains(node) || !dismissOnOutside,
    onDismiss
  );

  return presence;
};

"use client";
import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

let query: MediaQueryList | null = null;
const getQuery = () => {
  if (!query && typeof window !== "undefined") query = window.matchMedia(QUERY);
  return query;
};

/**
 * A simulated setting, used by X-ray mode so anyone can see what every
 * component does with reduced motion without changing their OS setting.
 * null means "follow the system".
 */
let simulated: boolean | null = null;
const simulationListeners = new Set<() => void>();

/** Override the system setting (true or false), or pass null to follow it again. */
export const simulateReducedMotion = (value: boolean | null) => {
  if (simulated === value) return;
  simulated = value;
  simulationListeners.forEach((notify) => notify());
};

/** Whether the reduced-motion setting is currently simulated rather than read from the system. */
export const reducedMotionSimulated = (): boolean => simulated !== null;

/**
 * Whether the user has asked for reduced motion, read live. Cheap enough to
 * call every frame inside a rAF loop, so the setting takes effect mid-animation.
 */
export const reducedMotionNow = (): boolean => simulated ?? getQuery()?.matches ?? false;

/**
 * Seconds to feed into time-based colour drift (`pastelColour`, `colourField`).
 * With reduced motion the clock stops, so colour still follows the user but no
 * longer drifts on its own.
 */
export const motionTime = (): number => (reducedMotionNow() ? 0 : performance.now() / 1000);

const subscribe = (notify: () => void) => {
  const q = getQuery();
  q?.addEventListener("change", notify);
  simulationListeners.add(notify);
  return () => {
    q?.removeEventListener("change", notify);
    simulationListeners.delete(notify);
  };
};

/** React hook for the same setting. The server snapshot is false, so first paint matches. */
export const useReducedMotion = (): boolean =>
  useSyncExternalStore(subscribe, reducedMotionNow, () => false);
